  /// may be empty when the server accepts open registrations.
  Future<SyncSummary> registerSync({
    required String serverUrl,
    required List<int> password,
    required String secretKey,
    required String deviceName,
    required String invite,
  }) => RustLib.instance.api.crateApiVaultVaultHandleRegisterSync(
    that: this,
    serverUrl: serverUrl,
    password: password,
    secretKey: secretKey,
    deviceName: deviceName,
    invite: invite,
  );

  /// Moves all items of group `from` to `to` (empty `to` ungroups them);
  /// returns how many were moved.
  Future<int> renameGroup({required String from, required String to}) => RustLib
      .instance
      .api
      .crateApiVaultVaultHandleRenameGroup(that: this, from: from, to: to);

  /// Sets up this empty database from an existing server account and
  /// leaves it unlocked.
  Future<SyncSummary> signIn({
    required String serverUrl,
    required List<int> password,
    required String secretKey,
    required String deviceName,
  }) => RustLib.instance.api.crateApiVaultVaultHandleSignIn(
    that: this,
    serverUrl: serverUrl,
    password: password,
    secretKey: secretKey,
    deviceName: deviceName,
  );

  /// Signs this device out and erases the local account; the app goes
  /// back to first-launch setup.
  Future<void> signOut() =>
      RustLib.instance.api.crateApiVaultVaultHandleSignOut(that: this);

  /// Server of the sync link (requires unlock).
  Future<SyncInfo?> syncInfo() =>
      RustLib.instance.api.crateApiVaultVaultHandleSyncInfo(that: this);

  Future<SyncSummary> syncNow() =>
      RustLib.instance.api.crateApiVaultVaultHandleSyncNow(that: this);

  /// Stops syncing this device; local data is kept.
  Future<void> unlinkSync() =>
      RustLib.instance.api.crateApiVaultVaultHandleUnlinkSync(that: this);

  Future<void> unlock({
    required List<int> password,
    required String secretKey,
  }) => RustLib.instance.api.crateApiVaultVaultHandleUnlock(
    that: this,
    password: password,
    secretKey: secretKey,
  );

  Future<VaultItem> updateItem({
    required String id,
    required ItemFields fields,
  }) => RustLib.instance.api.crateApiVaultVaultHandleUpdateItem(
    that: this,
    id: id,
    fields: fields,
  );
}
